// Meta WhatsApp Webhook Challenge Handshake
const query = $input.first().json.query || $input.first().json.params || {};
const mode = query['hub.mode'];
const challenge = query['hub.challenge'];
const token = query['hub.verify_token'];
const expectedToken = $env.META_WHATSAPP_VERIFY_TOKEN || 'netra_whatsapp_verify_token_2026';

if (mode === 'subscribe' && (!token || token === expectedToken)) {
  return {
    json: {
      status: 200,
      challenge: challenge || 'OK'
    }
  };
}

return {
  json: {
    status: 403,
    challenge: 'Forbidden'
  }
};

// Normalization Code Node for Meta WhatsApp Webhook & Direct Payloads
const input = $input.first().json;
const body = input.body || input;

let sender_id = 'community_user';
let media_type = 'text';
let content = '';
let message_id = '';
let phone_number_id = '';

// 1. Meta WhatsApp Cloud API Webhook Notification Format
if (body.entry && Array.isArray(body.entry) && body.entry.length > 0) {
  const entry0 = body.entry[0];
  const changes0 = (entry0.changes && entry0.changes.length > 0) ? entry0.changes[0] : null;
  const value = changes0 ? changes0.value : null;

  if (value) {
    if (value.metadata && value.metadata.phone_number_id) {
      phone_number_id = value.metadata.phone_number_id;
    }
    if (value.messages && Array.isArray(value.messages) && value.messages.length > 0) {
      const msg = value.messages[0];
      sender_id = msg.from || (value.contacts && value.contacts[0] ? value.contacts[0].wa_id : 'community_user');
      message_id = msg.id || '';
      const rawType = msg.type || 'text';

      if (rawType === 'text') {
        media_type = 'text';
        content = (msg.text && msg.text.body) ? msg.text.body : '';
      } else if (rawType === 'image') {
        media_type = 'image';
        content = (msg.image && (msg.image.url || msg.image.id)) ? (msg.image.url || msg.image.id) : (msg.caption || '');
      } else if (rawType === 'video') {
        media_type = 'video';
        content = (msg.video && (msg.video.url || msg.video.id)) ? (msg.video.url || msg.video.id) : (msg.caption || '');
      } else if (rawType === 'audio' || rawType === 'voice') {
        media_type = 'audio';
        const audObj = msg.audio || msg.voice;
        content = (audObj && (audObj.url || audObj.id)) ? (audObj.url || audObj.id) : '';
      } else {
        media_type = 'text';
        content = msg.caption || '';
      }
    }
  }
} else {
  // 2. Flattened Direct Payloads ($json.body.media_type / $json.body.text for testing)
  sender_id = body.sender_id || body.sender || body.from || 'community_user';
  media_type = (body.media_type || 'text').toLowerCase();
  message_id = body.message_id || body.id || `wamid.direct_${Date.now()}`;
  phone_number_id = body.phone_number_id || '';

  if (media_type === 'text') {
    content = body.content || body.text || '';
  } else if (media_type === 'image') {
    content = body.content || body.image_url || body.image || '';
  } else if (media_type === 'video') {
    content = body.content || body.video_url || body.video || '';
  } else if (media_type === 'audio') {
    content = body.content || body.audio_url || body.audio || '';
  } else {
    content = body.content || body.text || '';
  }
}

// Normalize sender_id
sender_id = String(sender_id).replace(/^whatsapp:/i, '').replace(/^\+/, '');

return {
  json: {
    sender_id,
    media_type,
    content,
    message_id,
    phone_number_id,
    source_platform: 'whatsapp',
    raw_body: body
  }
};

// Format Institutional Cybercrime Response with Statutory Citations
let evalResult = {};
try {
  evalResult = $('Threat Severity Gate').first().json;
} catch (e) {
  evalResult = $input.first().json;
}

let normalizer = {};
try {
  normalizer = $('Normalize WhatsApp Payload').first().json;
} catch (e) {}

const inputJson = $input.first().json;
let catalogId = inputJson.catalog_id || evalResult.catalog_id || null;
try {
  if (!catalogId && $('Index in Threat Catalog').all().length > 0) {
    catalogId = $('Index in Threat Catalog').first().json.catalog_id || null;
  }
} catch (e) {}

const isScam = evalResult.is_scam === true;
const risk = evalResult.risk_score || 0;
const typ = (evalResult.scam_type || 'Cyber Threat').replace(/_/g, ' ').toUpperCase();
const reason = evalResult.analysis_reason || 'Identified via NETRA AI multi-modal forensic inspection.';
const iocs = evalResult.extracted_iocs || {};
const sender_id = normalizer.sender_id || evalResult.sender_id || 'community_user';
const message_id = normalizer.message_id || '';

let msg = '';
if (isScam || risk >= 70) {
  msg = `🚨 *NETRA CRIME ALERT: ${typ} DETECTED*\n\n` +
        `• *Verdict:* FRAUD / CYBER THREAT DETECTED\n` +
        `• *Risk Score:* ${risk}% (CRITICAL THREAT)\n` +
        `• *Findings:* ${reason}\n` +
        (catalogId ? `• *Threat Catalog ID:* ${catalogId}\n` : '') +
        `• *Statutory Citations:* BNS 2023 Sec 318(4) & IT Act 2000 Sec 66D\n`;
  if (iocs.urls && iocs.urls.length) msg += `• *Flagged Domains/URLs:* ${iocs.urls.join(', ')}\n`;
  if (iocs.upis && iocs.upis.length) msg += `• *Attacker UPI:* ${iocs.upis.join(', ')}\n`;
  if (iocs.phones && iocs.phones.length) msg += `• *Attacker Phone:* ${iocs.phones.join(', ')}\n`;
  msg += `\n⚠️ *Advisory:* Never share OTPs, download unverified APKs, or send money. Report immediately to National Cyber Helpline *1930*.`;
} else {
  msg = `✅ *NETRA Verification: AUTHENTIC / LOW RISK*\n\n` +
        `• *Verdict:* AUTHENTIC\n` +
        `• *Risk Score:* ${risk}%\n` +
        `• *Findings:* No malicious patterns or generative artifacts identified.\n` +
        `• *Statutory Reference:* BNS 2023 Sec 318(4) & IT Act 2000 Sec 66D\n` +
        `\n⚠️ *Advisory:* Stay vigilant. For cyber extortion or online scams, contact *1930*.`;
}

return {
  json: {
    status: "success",
    is_scam: isScam,
    risk_score: risk,
    scam_type: evalResult.scam_type,
    catalog_id: catalogId,
    sender_id: sender_id,
    message_id: message_id,
    message: msg,
    timestamp: new Date().toISOString()
  }
};

// Format 24-Hour Autonomous Threat Intelligence Bulletin
const input = $input.first().json;
const feed = input.feed || [];

let bulletin = `📢 *NETRA 24-HOUR NATIONAL CYBER THREAT BULLETIN*\n` +
               `*Autonomous Intelligence Feed | Powered by Tavily & NETRA Core*\n\n`;

if (feed.length === 0) {
  bulletin += `• No critical national threat escalations recorded in the past 24 hours.\n` +
              `• Surveillance radar continues normal monitoring.\n\n`;
} else {
  feed.slice(0, 3).forEach((item, index) => {
    const title = item.title || 'Emerging Cyber Fraud Wave';
    const src = item.source || 'National Cybercrime Feed';
    const summary = item.summary || item.snippet || 'High vigilance advised for suspicious digital communications.';
    bulletin += `*${index + 1}. ${title}*\n` +
                `• *Source:* ${src}\n` +
                `• *Intel:* ${summary}\n\n`;
  });
}

bulletin += `⚖️ *Statutory Citations:* BNS 2023 Sec 318(4) & IT Act 2000 Sec 66D\n` +
            `🚨 *National Cyber Helpline:* 1930 | Report at https://cybercrime.gov.in\n` +
            `🛡️ *NETRA Cyber Defense Division*`;

return {
  json: {
    bulletin_text: bulletin,
    subscriber_recipient: $env.WHATSAPP_BROADCAST_RECIPIENT || '919876543210',
    timestamp: new Date().toISOString(),
    news_count: feed.length
  }
};
